#include <cstdio>
#include <vector>
#include <string>
#include <queue>
#include <sstream>
#include <iostream>

struct Node {
    int val;
    Node *left, *right;
    Node(int v) : val(v), left(nullptr), right(nullptr) {}
};

int lca(Node* root, int p, int q) {
    Node* node = root;
    while (node) {
        if (p < node->val && q < node->val) node = node->left;
        else if (p > node->val && q > node->val) node = node->right;
        else return node->val;
    }
    return -1;
}

int main() {
    std::string line, qline;
    std::getline(std::cin, line);
    std::getline(std::cin, qline);
    std::istringstream iss(line);
    std::vector<std::string> tok;
    std::string t;
    while (iss >> t) tok.push_back(t);
    std::istringstream qs(qline);
    int p, q; qs >> p >> q;

    std::vector<Node*> nodes(tok.size(), nullptr);
    nodes[0] = new Node(std::stoi(tok[0]));
    std::queue<int> dq;
    dq.push(0);
    size_t i = 1;
    while (!dq.empty() && i < tok.size()) {
        int idx = dq.front(); dq.pop();
        if (i < tok.size()) {
            if (tok[i] != "null") {
                nodes[i] = new Node(std::stoi(tok[i]));
                nodes[idx]->left = nodes[i];
                dq.push((int)i);
            }
            ++i;
        }
        if (i < tok.size()) {
            if (tok[i] != "null") {
                nodes[i] = new Node(std::stoi(tok[i]));
                nodes[idx]->right = nodes[i];
                dq.push((int)i);
            }
            ++i;
        }
    }
    printf("%d\n", lca(nodes[0], p, q));
    return 0;
}
